{
  int keeping, busy;

  keeping = parm + parm;
  busy = keeping * keeping;

  return busy;
}

int
subr (int parm)
{
  int keeping, busy;

  keeping = parm + parm;
  busy = keeping * keeping;

  return busy;
}

